THOUGHT: The IRC gateway is not present yet, so I’ll add a standalone shared-database gateway handling token PASS, registration numerics, nick collision, PING, accepted commands, unknown-command 421 replies, and QUIT. I’ll also supervise it from `start.sh` as an independent process on port 6667.

```mswea_bash_command
cat > /app/irc.py <<'PY'
import socket,threading,sqlite3,os
DB='/app/data/huddle.db'
def token_user(tok):
 c=sqlite3.connect(DB); r=c.execute('SELECT u.id,u.username FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(tok,)).fetchone(); c.close(); return r
nicks=set(); lock=threading.Lock()
def send(s,nick,text): s.sendall((':huddle '+text.replace('{nick}',nick)+'\r\n').encode())
def client(s,addr):
 nick=None; user=None; passed=False; registered=False
 try:
  buf=b''
  while True:
   x=s.recv(4096)
   if not x: break
   buf+=x
   while b'\n' in buf:
    raw,buf=buf.split(b'\n',1); line=raw.rstrip(b'\r').decode(errors='replace'); parts=line.split(' ',1); cmd=parts[0].upper(); arg=parts[1] if len(parts)>1 else ''
    if cmd=='PASS':
     tok=arg[1:] if arg.startswith(':') else arg; user=token_user(tok)
     if not user: send(s,nick or '*','464 {nick} :Password incorrect')
     else: passed=True
    elif cmd=='NICK':
     nn=arg.lstrip(':').split()[0] if arg else ''
     with lock: busy=nn in nicks and nn!=nick
     if busy: send(s,nn,'433 {nick} '+nn+' :Nickname is already in use')
     elif nn:
      with lock:
       if nick: nicks.discard(nick)
       nicks.add(nn)
      nick=nn
    elif cmd=='USER':
     if arg: registered=True
    elif cmd=='PING':
     val=arg[1:] if arg.startswith(':') else arg; s.sendall((':huddle PONG huddle :'+val+'\r\n').encode())
    elif cmd=='QUIT': return
    elif cmd in ('NAMES','WHO','LIST','TOPIC','MODE','PONG'): 
     if cmd=='NAMES': send(s,nick or '*','353 '+(nick or '*')+' = * :')
     elif cmd=='WHO': send(s,nick or '*','315 '+(nick or '*')+' :End of WHO list')
     elif cmd=='LIST': send(s,nick or '*','323 '+(nick or '*')+' :End of LIST')
     elif cmd=='TOPIC': send(s,nick or '*','331 '+(nick or '*')+' :No topic is set')
     elif cmd=='MODE': send(s,nick or '*','221 '+(nick or '*')+' +i')
    else: send(s,nick or '*','421 '+cmd+' :Unknown command')
    if passed and registered and nick and not getattr(s,'done',False):
     s.done=True
     for num,text in [('001','Welcome to Huddle'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle huddle 1.0 o o'),('005','CHANTYPES=# :are supported'),('422',':MOTD File is missing')]: send(s,nick,num+' '+nick+' :'+text)
 finally:
  with lock:
   if nick: nicks.discard(nick)
  s.close()
def main():
 srv=socket.socket(); srv.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1); srv.bind(('0.0.0.0',6667)); srv.listen()
 while True:
  s,a=srv.accept(); threading.Thread(target=client,args=(s,a),daemon=True).start()
if __name__=='__main__': main()
