 (d.channels||[]).forEach(c=>{const e=document.createElement('div');e.className='channel-entry';e.dataset.testid='channel-entry';e.dataset.channelId=c.id;e.dataset.channelName=c.name;e.textContent='#'+c.name;e.onclick=()=>openChannel(c);list.append(e)});
 if(!channel&&d.channels&&d.channels[0]) openChannel(d.channels[0]);
}
