  const h={...(opt.headers||{})};
  if(!('Content-Type' in h)&&opt.body) h['Content-Type']='application/json';
  const t=localStorage.getItem('huddle.token'); if(t) h.Authorization='Bearer '+t;
  const r=await fetch('/api'+path,{...opt,headers:h}); let j={}; try{j=await r.json()}catch{}; return {ok:r.ok,status:r.status,data:j};
};
let mode='register', me=null, workspace=null, channel=null, ws=null;
function showAuth(){ $('#auth-modal').hidden=false; const f=$('[data-testid=auth-form]'); f.dataset.mode=mode; $('[data-testid=auth-submit]').textContent=mode==='register'?'Sign up':'Log in'; $('[data-testid=auth-toggle]').textContent=mode==='register'?'Log in':'Create account'; }
function hideAuth(){ $('#auth-modal').hidden=true; }
function alertText(x){let a=$('[data-testid=auth-error]');a.setAttribute('role','alert');a.textContent=x||'';a.style.display=x?'block':'none'}
async function loadUser(){
 const q=new URLSearchParams(location.search), qt=q.get('token');
 if(qt){localStorage.setItem('huddle.token',qt)}
 const r=await api('/auth/me'); if(!r.ok){showAuth();return}
 me=r.data.user; hideAuth(); $('[data-testid=current-user]').textContent=me.username;
