 const r=await fetch('/api/auth/'+(mode==='register'?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:f.get('username'),password:f.get('password'),display_name:f.get('display_name')||undefined})});
 let d={};try{d=await r.json()}catch{};if(!r.ok){alertText(d.error||'Invalid input');return}
 localStorage.setItem('huddle.token',d.token);me=d.user;await loadUser();
};
$('[data-testid=logout-btn]').onclick=()=>{localStorage.removeItem('huddle.token');if(ws)ws.close();me=null;mode='register';showAuth()};
