THOUGHT: The source contains the expected control names, but the browser still reports no matching elements, so I’ll make the controls and reply-count elements part of the row’s initial HTML via `innerHTML` before attaching handlers. This avoids any DOM construction or attribute-assignment ambiguity and keeps the selectors directly discoverable.

```mswea_bash_command
python3 - <<'PY'
p='/app/static/app.js'; s=open(p).read()
start=s.index('function renderMessage(m){')
end=s.index('\\nfunction renderReactions',start)
new="""function renderMessage(m){
 const box=$('[data-testid=message-list]');if(box.querySelector('[data-testid=empty-state]'))box.innerHTML='';
 const e=document.createElement('article');e.className='message';e.setAttribute('data-testid','message');e.dataset.messageId=m.id;
 const name=(m.author?.display_name||m.author?.username||'User'), initial=(name[0]||'?').toUpperCase();
 e.innerHTML='<span data-testid="message-avatar">'+initial+'</span><span data-testid="message-author">'+name+'</span><time data-testid="message-time">'+fmt(m.created_at)+'</time><span data-testid="message-body"></span><span class="toolbar"><button data-testid="edit-message-btn" type="button">Edit</button><button data-testid="delete-message-btn" type="button">Delete</button><button data-testid="open-thread-btn" type="button">Replies</button><span data-testid="reply-count"></span><button data-testid="reaction-button" type="button">React</button></span>';
 e.querySelector('[data-testid="message-body"]').textContent=m.body;
 if(m.edited_at){const z=document.createElement('span');z.setAttribute('data-testid','edited-indicator');z.textContent=' (edited)';e.append(z)}
 const rc=e.querySelector('[data-testid="reply-count"]');rc.textContent=m.reply_count?(m.reply_count+' '+(m.reply_count===1?'reply':'replies')):'';
 e.querySelector('[data-testid="edit-message-btn"]').onclick=()=>editRow(e,m);
 e.querySelector('[data-testid="delete-message-btn"]').onclick=async()=>{const r=await api('/messages/'+m.id,{method:'DELETE'});if(r.ok)e.remove()};
 e.querySelector('[data-testid="open-thread-btn"]').onclick=()=>openThread(m);
 e.querySelector('[data-testid="reaction-button"]').onclick=()=>showPicker(e,m);
 renderReactions(e,m);box.append(e)
}"""
open(p,'w').write(s[:start]+new+s[end:])
PY
node --check /app/static/app.js && bash /spec/restart.sh && bash /spec/step.sh
```

